"""Atomic file replace that writes through symlinks to the final referent."""
import errno
import os
import stat
import tempfile


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _resolve_final(path)
    directory = os.path.dirname(dest) or "."
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _write_all(fd, raw):
    view = memoryview(raw)
    offset = 0
    while offset < len(view):
        try:
            n = os.write(fd, view[offset:])
        except InterruptedError:
            continue
        if n == 0:
            raise OSError("empty write")
        offset += n


def _resolve_final(path):
    if not os.path.isabs(path):
        path = os.path.join(os.getcwd(), path)
    components = [c for c in path.split(os.sep) if c]
    return _walk("/" if os.path.isabs(path) else os.getcwd(), components, [])


def _walk(current, components, stack):
    i = 0
    while i < len(components):
        comp = components[i]
        if comp == ".":
            i += 1
            continue
        if comp == "..":
            parent = os.path.dirname(current)
            if parent:
                current = parent
            i += 1
            continue

        nxt = os.path.join(current, comp)
        try:
            st = os.lstat(nxt)
        except OSError:
            for rest in components[i + 1 :]:
                if rest == ".":
                    continue
                if rest == "..":
                    parent = os.path.dirname(nxt)
                    if parent:
                        nxt = parent
                else:
                    nxt = os.path.join(nxt, rest)
            return nxt

        if stat.S_ISLNK(st.st_mode):
            ident = (st.st_dev, st.st_ino)
            if ident in stack:
                raise OSError(errno.ELOOP, "symlink cycle", nxt)
            target = os.readlink(nxt)
            tparts = [c for c in target.split(os.sep) if c]
            if os.path.isabs(target):
                base = "/"
            else:
                base = current
            current = _walk(base, tparts, stack + [ident])
            i += 1
            continue

        current = nxt
        i += 1
    return current

"""Atomic file replace through a path that may be a symlink chain."""
import os
import stat
import tempfile


def _joinrealpath(path, rest, seen):
    sep = os.sep
    if os.path.isabs(rest):
        drive, rest = os.path.splitdrive(rest)
        if rest.startswith(sep):
            rest = rest[len(sep):]
        path = drive + sep

    while rest:
        name, _, rest = rest.partition(sep)
        if not name or name == os.curdir:
            continue
        if name == os.pardir:
            if path:
                path, prev = os.path.split(path)
                if prev == os.pardir:
                    path = os.path.join(path, os.pardir, os.pardir)
            continue
        newpath = os.path.join(path, name)
        try:
            st = os.lstat(newpath)
        except OSError:
            if rest:
                return os.path.join(newpath, rest), False
            return newpath, False
        if not stat.S_ISLNK(st.st_mode):
            path = newpath
            continue
        if newpath in seen:
            resolved = seen[newpath]
            if resolved is not None:
                path = resolved
                continue
            raise OSError("symlink cycle")
        seen[newpath] = None
        path, ok = _joinrealpath(path, os.readlink(newpath), seen)
        if not ok:
            if rest:
                return os.path.join(path, rest), False
            return path, False
        seen[newpath] = path
    return path, True


def _final_referent(path):
    path = os.fspath(path)
    if not os.path.isabs(path):
        path = os.path.join(os.getcwd(), path)
    resolved, _ok = _joinrealpath("", path, {})
    return resolved


def _write_all(fd, raw):
    offset = 0
    view = memoryview(raw)
    while offset < len(raw):
        try:
            n = os.write(fd, view[offset:])
        except InterruptedError:
            continue
        if n == 0:
            raise OSError("short write")
        offset += n


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _final_referent(path)
    directory = os.path.dirname(dest) or "."
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            os.close(fd)
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise

"""Atomic file replace — follow symlink referents, never the named link."""
import os
import tempfile

_MAX_SYMLINKS = 40


def _write_all(fd, raw):
    view = memoryview(raw)
    offset = 0
    while offset < len(view):
        try:
            n = os.write(fd, view[offset:])
        except InterruptedError:
            continue
        if n == 0:
            raise OSError("empty write")
        offset += n


def _parts(path):
    return [p for p in path.split(os.sep) if p and p != "."]


def _resolve_referent(path):
    """Walk path with POSIX symlink semantics (follow before applying '..')."""
    if os.path.isabs(path):
        current = os.sep
        parts = _parts(path)
    else:
        current = os.getcwd()
        parts = _parts(path)

    leaf_seen = set()
    hops = 0
    i = 0
    while i < len(parts):
        part = parts[i]
        if part == "..":
            parent = os.path.dirname(current)
            current = parent if parent else os.sep
            i += 1
            continue

        candidate = os.path.join(current, part)
        if os.path.islink(candidate):
            hops += 1
            if hops > _MAX_SYMLINKS:
                raise OSError("Too many levels of symbolic links")
            rest = parts[i + 1 :]
            if not rest:
                if candidate in leaf_seen:
                    raise OSError("symbolic link cycle")
                leaf_seen.add(candidate)
            target = os.readlink(candidate)
            if os.path.isabs(target):
                current = os.sep
                tparts = _parts(target)
            else:
                tparts = _parts(target)
            parts = tparts + rest
            i = 0
            continue

        current = candidate
        i += 1

    return current


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _resolve_referent(path)
    directory = os.path.dirname(dest) or os.sep
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise

"""Atomic file replace that follows symlink referents."""
import os
import tempfile


def _write_all(fd, data):
    mv = memoryview(data)
    while mv:
        try:
            n = os.write(fd, mv)
        except InterruptedError:
            continue
        if n == 0:
            raise OSError("empty write")
        mv = mv[n:]


def _resolve_referent(path):
    """Return the path to replace, following a symlink chain to the leaf.

    Relative targets are anchored to each link's directory. ``..`` is applied
    after following a symlink, not collapsed lexically. Reusing the same
    symlink later in a finite walk is not a cycle; a closed loop raises
    OSError.
    """
    if os.path.isabs(path):
        current = os.sep
        remaining = [c for c in path.split(os.sep) if c]
    else:
        current = os.getcwd()
        remaining = [c for c in path.split(os.sep) if c]

    seen = set()
    while remaining:
        comp = remaining.pop(0)
        if comp == ".":
            continue
        if comp == "..":
            parent = os.path.dirname(current)
            current = parent if parent else current
            continue

        candidate = os.path.join(current, comp)
        if os.path.islink(candidate):
            st = os.lstat(candidate)
            ident = (st.st_dev, st.st_ino)
            if ident in seen:
                raise OSError("symlink cycle")
            seen.add(ident)
            target = os.readlink(candidate)
            if os.path.isabs(target):
                remaining = [c for c in target.split(os.sep) if c] + remaining
                current = os.sep
            else:
                remaining = [c for c in target.split(os.sep) if c] + remaining
            continue

        current = candidate
        seen = set()

    return current


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _resolve_referent(path)
    directory = os.path.dirname(dest) or os.sep
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise

"""Atomic file replace through a symlink chain."""
import os
import tempfile


def _joinrealpath(path, rest, seen):
    sep = os.sep
    curdir = os.curdir
    pardir = os.pardir

    if os.path.isabs(rest):
        rest = rest[len(sep):] if rest.startswith(sep) else rest
        path = sep

    while rest:
        name, _, rest = rest.partition(sep)
        if not name or name == curdir:
            continue
        if name == pardir:
            if path and path != sep:
                path = os.path.dirname(path)
            continue
        newpath = os.path.join(path, name)
        if not os.path.islink(newpath):
            path = newpath
            continue
        if newpath in seen:
            cached = seen[newpath]
            if cached is not None:
                path = cached
                continue
            raise OSError("Symlink cycle detected")
        seen[newpath] = None
        target = os.readlink(newpath)
        path, ok = _joinrealpath(path, target, seen)
        seen[newpath] = path
        if not ok:
            return (os.path.join(path, rest) if rest else path), False
    return path, True


def _resolve_referent(path):
    path = os.fspath(path)
    if not os.path.isabs(path):
        path = os.path.join(os.getcwd(), path)
    resolved, _ = _joinrealpath("", path, {})
    return resolved


def _write_all(fd, raw):
    view = memoryview(raw)
    offset = 0
    while offset < len(view):
        try:
            n = os.write(fd, view[offset:])
        except InterruptedError:
            continue
        if n == 0:
            raise OSError("empty write")
        offset += n


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _resolve_referent(path)
    directory = os.path.dirname(dest) or "."
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise

"""Atomic file replace — writes the final referent, leaving symlink paths intact."""
import os
import tempfile


def replace_file(path, data):
    raw = data if isinstance(data, bytes) else data.encode()
    dest = _resolve_final(path)
    directory = os.path.dirname(dest) or "."
    fd, tmp = tempfile.mkstemp(prefix=".replace-", dir=directory)
    try:
        _write_all(fd, raw)
        os.close(fd)
        fd = None
        os.replace(tmp, dest)
    except Exception:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _write_all(fd, raw):
    offset = 0
    while offset < len(raw):
        try:
            n = os.write(fd, raw[offset:])
        except InterruptedError:
            continue
        if not n:
            raise OSError("short write")
        offset += n


def _resolve_final(path):
    if os.path.isabs(path):
        current = os.path.abspath(os.sep)
        parts = [p for p in path.split(os.sep) if p]
    else:
        current = os.getcwd()
        parts = [p for p in path.split(os.sep) if p]
    return _walk(current, parts, set())


def _walk(current, parts, seen):
    i = 0
    while i < len(parts):
        part = parts[i]
        i += 1
        if part in (".", ""):
            continue
        if part == "..":
            parent = os.path.dirname(current)
            current = parent if parent else current
            continue
        candidate = os.path.join(current, part)
        if os.path.islink(candidate):
            st = os.lstat(candidate)
            ident = (st.st_dev, st.st_ino)
            if ident in seen:
                raise OSError("symlink cycle detected")
            target = os.readlink(candidate)
            link_dir = os.path.dirname(candidate) or os.sep
            if os.path.isabs(target):
                t_current = os.path.abspath(os.sep)
                t_parts = [p for p in target.split(os.sep) if p]
            else:
                t_current = link_dir
                t_parts = [p for p in target.split(os.sep) if p]
            current = _walk(t_current, t_parts, seen | {ident})
        else:
            current = candidate
    return current

