"""Prompt-cache affinity — git-root seed so sibling worktrees share a cache."""
import hashlib
import os

CACHE_SALT = "graff-cache-affinity-v2"
SCRATCH_SEED = "graff-scratch"


def git_root_of(cwd):
    path = os.path.abspath(cwd)
    while True:
        git_marker = os.path.join(path, ".git")
        if os.path.lexists(git_marker):
            return path
        parent = os.path.dirname(path)
        if parent == path:
            return None
        path = parent


def affinity_seed(cwd):
    root = git_root_of(cwd)
    if root is not None:
        return root
    return SCRATCH_SEED


def cache_key(cwd):
    return hashlib.sha256((CACHE_SALT + affinity_seed(cwd)).encode()).hexdigest()

