"""Streaming JSON iteration per SPEC.md."""
import json
import re


class DecodingError(Exception):
    pass


class StreamConsumed(Exception):
    pass


class Stream:
    def __init__(self, data):
        self.data = data
        self.consumed = False


def _media(ct):
    ct = (ct or "").split(";", 1)[0].strip().lower()
    return ct


def _loads(s):
    try:
        return json.loads(s)
    except json.JSONDecodeError as e:
        raise DecodingError(str(e)) from e


def iter_json(content_type, body, streaming=False):
    if isinstance(body, Stream):
        if streaming and body.consumed:
            raise StreamConsumed()
        data = body.data
        if streaming:
            body.consumed = True
    else:
        data = body

    media = _media(content_type)
    ok = (
        media == "application/json"
        or (media.startswith("application/") and media.endswith("+json"))
        or media in ("application/ndjson", "application/x-ndjson", "application/json-seq")
    )
    if not ok:
        raise DecodingError(media)

    if media in ("application/ndjson", "application/x-ndjson"):
        for line in re.split(r"\r\n|\n|\r", data):
            if not line:
                continue
            yield _loads(line)
        return

    if media == "application/json-seq":
        if not data:
            return
        parts = data.split("\x1e")
        # Records start with RS; text before the first RS is not a record.
        for part in parts[1:]:
            if part.endswith("\n"):
                part = part[:-1]
            if not part:
                continue
            yield _loads(part)
        return

    text = data.lstrip()
    try:
        val, end = json.JSONDecoder().raw_decode(text)
    except json.JSONDecodeError as e:
        raise DecodingError(str(e)) from e
    if text[end:].strip():
        raise DecodingError("trailing data")
    if isinstance(val, list):
        yield from val
    else:
        yield val

"""Streaming JSON iteration per SPEC.md."""
import json
import re


class DecodingError(Exception):
    pass


class StreamConsumed(Exception):
    pass


class Stream:
    def __init__(self, data):
        self.data = data
        self.consumed = False


def _media(ct):
    ct = (ct or "").split(";", 1)[0].strip().lower()
    return ct


def _accepts(media):
    if media in (
        "application/json",
        "application/ndjson",
        "application/x-ndjson",
        "application/json-seq",
    ):
        return True
    # +json is valid only under application/
    if media.startswith("application/") and media.endswith("+json"):
        return True
    return False


def iter_json(content_type, body, streaming=False):
    if isinstance(body, Stream):
        if streaming and body.consumed:
            raise StreamConsumed()
        data = body.data
        if streaming:
            body.consumed = True
    else:
        data = body

    media = _media(content_type)
    if not _accepts(media):
        raise DecodingError(media)

    if media in ("application/ndjson", "application/x-ndjson"):
        for line in re.split(r"\r\n|\n|\r", data):
            if not line.strip():
                continue
            yield json.loads(line)
        return

    if media == "application/json-seq":
        # Records start with RS (0x1e). Empty payload yields nothing.
        if not data:
            return
        parts = data.split("\x1e")
        for i, part in enumerate(parts):
            if i == 0:
                # Text before the first RS is not a record.
                continue
            if part.endswith("\n"):
                part = part[:-1]
            if not part:
                continue
            yield json.loads(part)
        return

    text = data.lstrip()
    val, end = json.JSONDecoder().raw_decode(text)
    if text[end:].strip():
        raise DecodingError("trailing data")
    if isinstance(val, list):
        yield from val
    else:
        yield val

