"""Validated / Invalid — error-accumulating applicative/monad-like containers."""


class Valid:
    __match_args__ = ("value",)

    def __init__(self, value):
        self.value = value

    def bind(self, fn):
        return fn(self.value)

    def apply(self, other):
        if isinstance(other, Invalid):
            return other
        return Valid(self.value(other.value))

    def swap(self):
        return Invalid((self.value,))

    def alt(self, fn):
        return self

    @classmethod
    def from_validated(cls, v):
        return v

    def __eq__(self, other):
        return type(other) is Valid and other.value == self.value

    def __repr__(self):
        return f"Valid({self.value!r})"


class Invalid:
    __match_args__ = ("errors",)

    def __init__(self, errors):
        if isinstance(errors, tuple):
            self.errors = errors
        elif isinstance(errors, (list, set)):
            self.errors = tuple(errors)
        else:
            self.errors = (errors,)

    @classmethod
    def from_failure(cls, err):
        return cls((err,))

